class Solution:
    def reverseOnlyLetters(self, s: str) -> str:
        st,sp=[],[]
        for i,ch in enumerate(s):
            if ch.isalpha():
                st.append(ch)
            else:
                sp.append([i,ch])
        st=st[::-1]
        for i in sp:
            st.insert(i[0],i[1])
        return (''.join(st))

class Solution:
    def maxSubarraySumCircular(self, A):
        total, max_sum, cur_max, min_sum, cur_min = 0, -float("inf"), 0, float("inf"), 0
        for a in A:
            cur_max = max(cur_max+a, a)
            max_sum = max(max_sum, cur_max)
            cur_min = min(cur_min+a, a)
            min_sum = min(min_sum, cur_min)
            total += a
        return max(max_sum, total-min_sum) if max_sum >= 0 else max_sum

class Solution:
    def numMusicPlaylists(self, n: int, goal: int, k: int) -> int:
        prev_p, cur_p = [0] * (n+1), [0] * (n+1)

        for i in range(k+1, goal+1):
            if i == k+1:
                prev_p[i] = math.factorial(n) // math.factorial(n-i)
            else:
                for j in range(k+1, min(i, n)+1):
                    cur_p[j] = prev_p[j-1] * (n - j + 1) + prev_p[j] * (j-k)
                prev_p, cur_p = cur_p, [0] * (n+1)
        return prev_p[n] % (10**9 + 7)

class Solution:
    def numMusicPlaylists(self, N, L, K):
        M = 10**9+7
        dp = [[0 for _ in range(1+L)] for _ in range(2)]
        dp[0][0] = dp[1][1] = 1
        for n in range(1, N+1):
            dp[n % 2][n] = (dp[(n-1) % 2][n-1] * n) % M
            for l in range(n+1, L+1):
                dp[n % 2][l] = ((dp[n % 2][l-1] * max(n-K, 0)) % M + \
                                (dp[(n-1) % 2][l-1] * n) % M) % M
        return dp[N % 2][L]

class Solution:
    def minAddToMakeValid(self, s: str) -> int:
        l, r = list(), list()
        for i in s:
            if i == "(":
                l.append(i)
            else:
                if l:
                    l.pop()
                else:
                    r.append(i)
        return len(l) + len(r)

class Solution:
    def minAddToMakeValid(self, S):
        add, bal, = 0, 0
        for c in S:
            bal += 1 if c == '(' else -1
            if bal == -1:
                add += 1
                bal += 1
        return add + bal

